<?php namespace App\Controllers;
final class AuthController{function form():void{if(\user())\redirect('/admin');\view('admin/login',['title'=>'Masuk Admin','noindex'=>true]);}function login():void{\verify_csrf();$email=mb_strtolower(trim((string)($_POST['email']??'')));$ih=hash('sha256',$email);$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'cli');$q=\db()->prepare("SELECT COUNT(*) FROM login_attempts WHERE identifier_hash=? AND ip_hash=? AND succeeded=0 AND attempted_at>UTC_TIMESTAMP()-INTERVAL 15 MINUTE");$q->execute([$ih,$ip]);if((int)$q->fetchColumn()>=5){$_SESSION['error']='Terlalu banyak percobaan. Coba lagi dalam 15 menit.';\redirect('/admin/login');}$u=\db()->prepare('SELECT * FROM users WHERE email=?');$u->execute([$email]);$row=$u->fetch();$ok=$row&&password_verify((string)($_POST['password']??''),$row['password_hash']);$log=\db()->prepare('INSERT INTO login_attempts(identifier_hash,ip_hash,succeeded) VALUES(?,?,?)');$log->execute([$ih,$ip,(int)$ok]);if(!$ok){$_SESSION['error']='Email atau kata sandi tidak cocok.';\redirect('/admin/login');}session_regenerate_id(true);$_SESSION['user']=['id'=>$row['id'],'name'=>$row['name'],'role'=>$row['role']];\redirect('/admin');}function logout():void{\verify_csrf();$_SESSION=[];session_destroy();\redirect('/admin/login');}}
